<script setup>
import { computed, onMounted, reactive, ref } from 'vue';
import { api } from '../api.js';
const props = defineProps({ path: String });
const id = computed(() => props.path.split('/')[1] || '');
const servers = ref([]), server = ref(null), tools = ref([]), error = ref(''), notice = ref(''), busy = ref(false), edit = ref(false), job = ref(null), chosen = ref(''), args = ref('{}');
const form = reactive({ name: '', transport: 'HTTP', url: '', command: '', args: '[]', token: '', enabled: true });
async function load() { error.value = ''; try { servers.value = await api('/api/mcp-servers'); if (id.value && id.value !== 'new') { server.value = await api(`/api/mcp-servers/${id.value}`); tools.value = await api(`/api/mcp-servers/${id.value}/tools`); Object.assign(form, server.value, { args: JSON.stringify(server.value.args || []), token: '' }); } } catch (e) { error.value = e.message; } }
async function save() { error.value = ''; busy.value = true; try { let values; try { values = JSON.parse(form.args); if (!Array.isArray(values)) throw new Error(); } catch { throw new Error('启动参数必须是 JSON 数组'); } const body = { name: form.name, transport: form.transport, url: form.url, command: form.command, args: values, token: form.token, enabled: form.enabled }; const result = await api(id.value === 'new' ? '/api/mcp-servers' : `/api/mcp-servers/${id.value}`, { method: id.value === 'new' ? 'POST' : 'PUT', body }); form.token = ''; location.hash = `#/mcp/${result.id}`; edit.value = false; await load(); } catch (e) { error.value = e.message; } finally { busy.value = false; } }
async function refresh() { busy.value = true; error.value = ''; try { tools.value = await api(`/api/mcp-servers/${id.value}/refresh`, { method: 'POST' }); server.value = await api(`/api/mcp-servers/${id.value}`); notice.value = '工具列表已刷新'; } catch (e) { error.value = e.message; } finally { busy.value = false; } }
async function toggleTool(tool) { try { await api(`/api/mcp-servers/${id.value}/tools/${encodeURIComponent(tool.name)}/enabled`, { method: 'POST', body: { enabled: !tool.enabled } }); await load(); } catch (e) { error.value = e.message; } }
async function toggleReadOnly(tool) { try { await api(`/api/mcp-servers/${id.value}/tools/${encodeURIComponent(tool.name)}/read-only`, { method: 'POST', body: { readOnly: !tool.readOnly } }); await load(); } catch (e) { error.value = e.message; } }
async function remove(item) { if (!window.confirm(`移除 MCP 服务“${item.name}”？`)) return; try { await api(`/api/mcp-servers/${item.id}`, { method: 'DELETE' }); location.hash = '#/mcp'; await load(); } catch (e) { error.value = e.message; } }
async function call() { busy.value = true; error.value = ''; job.value = null; try { let value; try { value = JSON.parse(args.value); } catch { throw new Error('工具参数必须是有效 JSON'); } job.value = await api('/api/mcp-calls', { method: 'POST', body: { serverId: id.value, toolName: chosen.value, args: value } }); } catch (e) { error.value = e.message; } finally { busy.value = false; } }
async function decide(decision) { busy.value = true; error.value = ''; try { job.value = await api(`/api/mcp-actions/${job.value.action.id}/${decision}`, { method: 'POST' }); } catch (e) { error.value = e.message; } finally { busy.value = false; } }
onMounted(load);
</script>
<template>
  <main class="content-page"><template v-if="!id"><div class="page-heading"><div><p class="eyebrow">EXTENSIONS</p><h1>MCP 服务</h1><p class="muted">注册外部服务、发现工具并管理可用状态。</p></div><a class="primary link-button" href="#/mcp/new">添加服务</a></div><p v-if="error" class="error" role="alert">{{ error }}</p><div v-if="!servers.length" class="empty-state"><div class="empty-symbol">⌘</div><h2>还没有 MCP 服务</h2><p>添加服务后，可以连接并发现其中的工具。</p><a href="#/mcp/new">添加服务 →</a></div><div v-else class="resource-grid"><article v-for="item in servers" :key="item.id" class="resource-card"><div class="resource-heading"><span class="resource-icon">MCP</span><span class="badge">{{ item.transport }}</span><span class="badge" :class="{green:item.enabled}">{{ item.enabled ? '已启用' : '已停用' }}</span></div><h2>{{ item.name }}</h2><p class="small muted mono">{{ item.transport === 'HTTP' ? item.url : item.command }}</p><div class="card-actions"><a :href="`#/mcp/${item.id}`">查看详情</a><button class="text-button danger" @click="remove(item)">移除</button></div></article></div></template>
    <template v-else><a class="back-link" href="#/mcp">← 返回 MCP 服务</a><div class="page-heading"><div><p class="eyebrow">MCP SERVICE</p><h1>{{ id === 'new' ? '添加服务' : server?.name || '服务详情' }}</h1><p class="muted">{{ id === 'new' ? '配置服务地址和访问凭据。' : '发现工具，查看模式并发起受控调用。' }}</p></div><button v-if="id !== 'new' && !edit" class="secondary" @click="edit=true">编辑配置</button></div><p v-if="error" class="error" role="alert">{{ error }}</p><p v-if="notice" class="notice" role="status">{{ notice }}</p>
      <form v-if="id === 'new' || edit" class="form-card" @submit.prevent="save"><label>服务名称<input v-model.trim="form.name" required></label><label>传输方式<select v-model="form.transport" :disabled="id !== 'new'"><option value="HTTP">Streamable HTTP</option><option value="STDIO">本地 STDIO</option></select></label><template v-if="form.transport === 'HTTP'"><label>服务地址<input v-model.trim="form.url" type="url" required placeholder="http://127.0.0.1:8000/mcp"></label><label>Bearer Token <span class="muted">（可选）</span><input v-model="form.token" type="password" autocomplete="new-password" :placeholder="id === 'new' ? '按服务要求填写' : '留空以保留原凭据'"></label></template><template v-else><label>启动命令<input v-model.trim="form.command" required placeholder="python3 或 node"></label><label>启动参数（JSON 数组）<input v-model="form.args" placeholder='["/本机脚本目录/server.py"]'></label><p class="muted small">支持本机 Python 或 Node 脚本。受限进程不能访问网络、写入宿主文件或启动其他程序；不支持 npx、uvx。请将脚本和依赖放在单独目录。</p></template><label class="check-label"><input v-model="form.enabled" type="checkbox"> 启用此服务</label><div class="form-actions"><button class="primary" :disabled="busy">保存配置</button><button v-if="id !== 'new'" type="button" class="secondary" @click="edit=false">取消</button></div></form>
      <template v-else-if="server"><div class="split-page"><section class="result-panel"><div class="panel-heading"><h2>已发现工具</h2><button class="secondary" :disabled="busy" @click="refresh">{{ busy ? '连接中…' : '连接并刷新' }}</button></div><p class="muted small">只有你明确标记为只读的工具才能在 Chat 模式直接调用；其余工具仅限 Build 并需要确认。</p><p v-if="!tools.length" class="quiet-state">尚未发现工具，点击“连接并刷新”。</p><article v-for="tool in tools" :key="tool.name" class="tool-row"><div><strong>{{ tool.name }}</strong><p class="muted small">{{ tool.description || '无描述' }}</p><div class="tool-health"><span class="badge" :class="{green:tool.readOnly}">{{ tool.readOnly ? 'Chat 只读' : 'Build 工具' }}</span><button class="text-button" @click="toggleReadOnly(tool)">{{ tool.readOnly ? '取消只读标记' : '标记为只读' }}</button></div></div><button class="text-button" @click="toggleTool(tool)">{{ tool.enabled ? '停用' : '启用' }}</button></article></section><section class="result-panel"><h2>调用工具</h2><form @submit.prevent="call"><label class="search-label">选择工具<select v-model="chosen" required><option value="" disabled>请选择工具</option><option v-for="tool in tools.filter(t => t.enabled)" :key="tool.name" :value="tool.name">{{ tool.name }}</option></select></label><p v-if="chosen" class="muted small">输入模式：{{ JSON.stringify(tools.find(t => t.name === chosen)?.inputSchema) }}</p><label class="search-label">参数 JSON<textarea v-model="args" class="mono" rows="8"></textarea></label><div class="form-actions"><button class="primary" :disabled="busy || !chosen">申请调用</button></div></form><div v-if="job?.action?.status === 'PENDING'" class="approval-card"><p class="eyebrow">需要你的确认</p><h3>外部 MCP 工具调用</h3><p>请核对工具名称和参数，确认后才会实际调用。</p><pre>{{ JSON.stringify(job.action.operation, null, 2) }}</pre><div class="form-actions"><button class="primary" :disabled="busy" @click="decide('approve')">确认执行</button><button class="secondary" :disabled="busy" @click="decide('reject')">拒绝</button></div></div><p v-if="job?.error" class="error">{{ job.error }}</p><pre v-if="job?.result">{{ JSON.stringify(job.result, null, 2) }}</pre></section></div></template>
    </template></main>
</template>
